function showContext(x,y,kind){const m=$('contextMenu');m.innerHTML='';const entries=kind==='object'?[['Duplizieren',duplicateObject],['Löschen',deleteObject],['Eine Ebene vor',()=>reorderObject(1)],['Eine Ebene zurück',()=>reorderObject(-1)],['Ganz nach vorne',()=>reorderObjectTo('front')],['Ganz nach hinten',()=>reorderObjectTo('back')],['Gruppieren',groupSelection],['Gruppe lösen',ungroupSelection],['Als Vorlage speichern',saveSelectionAsTemplate]]:[['Neue Folie',()=>addSlide(false)],['Folie duplizieren',()=>addSlide(true)],['Nach oben verschieben',()=>moveSlide(-1)],['Nach unten verschieben',()=>moveSlide(1)],['Folie löschen',deleteSlide]];entries.forEach(([label,fn],idx)=>{if(idx===2)m.appendChild(document.createElement('hr'));const b=document.createElement('button');b.textContent=label;b.onclick=()=>{hideContext();fn()};m.appendChild(b)});m.style.left=Math.min(x,innerWidth-210)+'px';m.style.top=Math.min(y,innerHeight-220)+'px';m.hidden=false}function hideContext(){$('contextMenu').hidden=true}document.addEventListener('pointerdown',e=>{if(!e.target.closest('#contextMenu'))hideContext()});function reorderObjectTo(where){const a=currentItems(),i=a.findIndex(x=>x.id===selected);if(i<0)return;const [v]=a.splice(i,1);where==='front'?a.push(v):a.unshift(v);render()}function reorderObject(delta){const a=currentItems(),i=a.findIndex(x=>x.id===selected),j=Math.max(0,Math.min(a.length-1,i+delta));if(i===j)return;const [v]=a.splice(i,1);a.splice(j,0,v);render()}
