function downloadText(filename,text,type='text/plain'){
  const blob=new Blob([text],{type}),a=document.createElement('a');
  a.href=URL.createObjectURL(blob);a.download=filename;a.click();
  setTimeout(()=>URL.revokeObjectURL(a.href),500);
}
function safeFileName(name){return String(name||'visual-programm').trim().replace(/[^a-z0-9äöüß_-]+/gi,'_').replace(/^_+|_+$/g,'')||'visual-programm'}
function buildStandaloneProgram(){
  const data=JSON.stringify(project).replace(/<\/script/gi,'<\\/script');
  return `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(project.name||'Visual Programm')}</title><style>
  *{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#111;font-family:Segoe UI,Arial,sans-serif}.app{width:100%;height:100%;display:grid;place-items:center}.page{position:relative;transform-origin:center;overflow:hidden}.i{position:absolute;padding:6px;overflow:hidden}.button{display:flex;align-items:center;justify-content:center;border-radius:6px;cursor:pointer}.input{border:1px solid #aaa}.panel,.table{border:1px solid #bbb}.ellipse{border-radius:50%}.triangle{clip-path:polygon(50% 0,100% 100%,0 100%)}.controls{position:fixed;right:12px;bottom:12px;display:flex;gap:8px;z-index:10}.controls button{border:0;border-radius:8px;padding:9px 12px;background:#fff;box-shadow:0 2px 10px #0005;cursor:pointer}@keyframes fade{from{opacity:0}to{opacity:1}}@keyframes zoom{from{transform:scale(.92);opacity:0}to{transform:scale(1);opacity:1}}@keyframes slideLeft{from{transform:translateX(12%);opacity:0}to{transform:none;opacity:1}}@keyframes slideRight{from{transform:translateX(-12%);opacity:0}to{transform:none;opacity:1}}
  </style></head><body><script id="fs-project-data" type="application/json">${data}<\/script><div class="app"><div id="page" class="page"></div></div><div class="controls"><button id="prev">‹</button><button id="play">Pause</button><button id="next">›</button></div><script>
  const project=JSON.parse(document.getElementById('fs-project-data').textContent);let index=0,timer=null,playing=true;const page=document.getElementById('page');
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const tableHtml=i=>{const rows=i.tableData||[];return '<table style="border-collapse:collapse;width:100%;height:100%;font-family:'+esc(i.tableFontFamily||'Arial')+';font-size:'+(i.tableFontSize||16)+'px;background:'+(i.tableBg||'#fff')+'">'+rows.map((row,r)=>'<tr>'+row.map(c=>c.hidden?'':'<'+((i.tableHeader!==false&&r===0)?'th':'td')+' colspan="'+(c.colSpan||1)+'" style="border:'+(i.tableBorderWidth??1)+'px '+(i.tableBorderStyle||'solid')+' '+(i.tableBorderColor||'#334155')+';padding:'+(i.tablePadding??6)+'px;text-align:'+(i.tableTextAlign||'left')+';vertical-align:'+(i.tableVerticalAlign||'middle')+';background:'+(c.bg||'transparent')+';color:'+(c.color||i.color||'#111')+'">'+esc(c.text||'')+'</'+((i.tableHeader!==false&&r===0)?'th':'td')+'>').join('')+'</tr>').join('')+'</table>'};
  function scale(){const s=Math.min(innerWidth/project.page.width,innerHeight/project.page.height);page.style.transform='scale('+s+')'}
  function render(){clearTimeout(timer);const slide=project.slides[index];page.style.width=project.page.width+'px';page.style.height=project.page.height+'px';page.style.backgroundColor=slide.bg;page.style.backgroundImage=slide.backgroundImage&&/^(linear-gradient|radial-gradient|conic-gradient)\(/i.test(slide.backgroundImage)?slide.backgroundImage:(slide.backgroundImage?'url("'+String(slide.backgroundImage).replace(/"/g,'')+'")':'none');page.style.backgroundSize=slide.backgroundFit==='stretch'?'100% 100%':slide.backgroundFit==='repeat'?'auto':(slide.backgroundFit||'cover');page.style.backgroundRepeat=slide.backgroundFit==='repeat'?'repeat':'no-repeat';page.style.backgroundPosition='center';page.style.animation='none';void page.offsetWidth;const anim=slide.transition==='fade'?'fade':slide.transition==='zoom'?'zoom':slide.transition==='slide-left'?'slideLeft':slide.transition==='slide-right'?'slideRight':'none';page.style.animation=anim+' '+Number(slide.transitionDuration||0)+'s';page.innerHTML=slide.items.map(i=>'<div class="i '+i.type+'" data-action="'+esc(i.action||'')+'" style="left:'+i.x+'px;top:'+i.y+'px;width:'+i.w+'px;height:'+i.h+'px;font-size:'+i.font+'px;color:'+i.color+';background-color:'+i.bg+';font-weight:'+(i.bold?700:400)+';text-align:'+i.align+';opacity:'+((i.opacity??100)/100)+';'+(i.type==='image'&&i.src?'background-image:url(\\''+String(i.src).replace(/'/g,'')+'\\');background-size:'+(i.fit==='stretch'?'100% 100%':i.fit)+';background-position:center;':'')+'">'+(i.type==='table'?tableHtml(i):(i.type==='image'&&i.src?'':esc(i.text)))+'</div>').join('');scale();if(playing)timer=setTimeout(()=>go(1),Math.max(1,Number(slide.duration||10))*1000)}
  function go(d){index=(index+d+project.slides.length)%project.slides.length;render()}document.getElementById('prev').onclick=()=>go(-1);document.getElementById('next').onclick=()=>go(1);document.getElementById('play').onclick=e=>{playing=!playing;e.target.textContent=playing?'Pause':'Start';render()};page.onclick=e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(a==='next-slide')go(1);if(a==='previous-slide')go(-1);if(a==='alert')alert(e.target.textContent)};addEventListener('resize',scale);render();
  <\/script></body></html>`;
}
