function showPreview(index,auto=false){clearTimeout(previewTimer);previewIndex=(index+project.slides.length)%project.slides.length;const s=project.slides[previewIndex];$('previewFrame').srcdoc=buildPreview(s);$('previewCounter').textContent=`${previewIndex+1} / ${project.slides.length} · ${s.name}`;if(auto&&($('previewLoop')?.checked||previewIndex<project.slides.length-1))previewTimer=setTimeout(()=>showPreview(previewIndex+1,true),Math.max(1,s.duration)*1000)}$('previewBtn').onclick=()=>{$('previewModal').hidden=false;showPreview(project.slides.findIndex(s=>s.id===activeSlideId),true)};$('previewPrev').onclick=()=>showPreview(previewIndex-1,false);$('previewNext').onclick=()=>showPreview(previewIndex+1,false);$('closePreview').onclick=()=>{clearTimeout(previewTimer);$('previewModal').hidden=true};$('previewFullscreen').onclick=async()=>{const box=$('previewModal').querySelector('.modalBox');try{if(!document.fullscreenElement)await box.requestFullscreen();else await document.exitFullscreen()}catch(e){status('Vollbild wurde vom Browser blockiert')}};
function buildPreview(slide){const items=slide.items.map(i=>`<div class="i ${i.type}" style="left:${i.x}px;top:${i.y}px;width:${i.w}px;height:${i.h}px;font-size:${i.font}px;color:${i.color};background-color:${i.bg};font-weight:${i.bold?700:400};text-align:${i.align};opacity:${(i.opacity??100)/100};${i.type==='image'&&i.src?`background-image:url('${i.src.replace(/'/g,'')}');background-size:${i.fit==='stretch'?'100% 100%':i.fit};background-position:center;`:''}">${i.type==='table'?tableToHtml(i):(i.type==='image'&&i.src?'':escapeHtml(i.text))}</div>`).join('');return `<!doctype html><meta charset="utf-8"><style>*{box-sizing:border-box}body{margin:0;font-family:Segoe UI,Arial;background:#222;overflow:auto}.page{position:relative;margin:20px auto;width:${project.page.width}px;height:${project.page.height}px;background-color:${slide.bg};background-image:${slide.backgroundImage?(/^(linear-gradient|radial-gradient|conic-gradient)\(/i.test(slide.backgroundImage)?slide.backgroundImage:`url('${slide.backgroundImage.replace(/'/g,'')}')`):'none'};background-size:${slide.backgroundFit==='stretch'?'100% 100%':slide.backgroundFit==='repeat'?'auto':slide.backgroundFit||'cover'};background-repeat:${slide.backgroundFit==='repeat'?'repeat':'no-repeat'};background-position:center;overflow:hidden;animation:${slide.transition==='fade'?'fade':slide.transition==='zoom'?'zoom':'none'} ${slide.transitionDuration}s}.i{position:absolute;padding:6px;overflow:hidden}.button{display:flex;align-items:center;justify-content:center;border-radius:6px}.input{border:1px solid #aaa}.panel,.table{border:1px solid #bbb}.ellipse{border-radius:50%}.triangle{clip-path:polygon(50% 0,100% 100%,0 100%)}@keyframes fade{from{opacity:0}to{opacity:1}}@keyframes zoom{from{transform:scale(.92);opacity:0}to{transform:scale(1);opacity:1}}</style><div class="page">${items}</div>`}

const AUTOSAVE_KEY='fs3.visualDesigner.autosave.v014',HISTORY_KEY='fs3.visualDesigner.history.v014';
let autosaveTimer=null,lastAutosaveHash='';
function projectHash(){try{return JSON.stringify(project)}catch{return''}}
function writeAutosave(force=false){const raw=projectHash();if(!force&&raw===lastAutosaveHash)return;lastAutosaveHash=raw;try{localStorage.setItem(AUTOSAVE_KEY,JSON.stringify({savedAt:new Date().toISOString(),project}));status('Automatisch gesichert')}catch(e){status('Automatische Sicherung fehlgeschlagen')}}
function scheduleAutosave(){clearTimeout(autosaveTimer);autosaveTimer=setTimeout(()=>writeAutosave(false),1500)}
const originalRender=render;render=function(){const r=originalRender.apply(this,arguments);scheduleAutosave();return r};
addEventListener('beforeunload',()=>writeAutosave(true));
function getHistory(){try{return JSON.parse(localStorage.getItem(HISTORY_KEY)||'[]')}catch{return[]}}
function setHistory(items){localStorage.setItem(HISTORY_KEY,JSON.stringify(items.slice(0,20)))}
function createSnapshot(label='Manuell'){const items=getHistory();items.unshift({id:uid('snapshot'),label,savedAt:new Date().toISOString(),project:JSON.parse(JSON.stringify(project))});setHistory(items);renderHistory();status('Projektstand gesichert')}
function renderHistory(){const box=$('historyList');if(!box)return;const items=getHistory();box.innerHTML='';if(!items.length){box.innerHTML='<p class="empty">Noch keine Projektstände vorhanden.</p>';return}items.forEach((s,idx)=>{const row=document.createElement('div');row.className='historyRow';const d=new Date(s.savedAt);row.innerHTML=`<div><strong>${escapeHtml(s.label||'Projektstand')}</strong><small>${d.toLocaleString('de-DE')} · ${s.project?.slides?.length||0} Folien</small></div><div><button data-restore="${idx}">Wiederherstellen</button><button data-delete="${idx}">Löschen</button></div>`;box.appendChild(row)});box.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>{const s=getHistory()[+b.dataset.restore];if(!s)return;project=migrate(JSON.parse(JSON.stringify(s.project)));activeSlideId=project.slides[0].id;selected=null;selectedIds=new Set();render();status('Projektstand wiederhergestellt')});box.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const a=getHistory();a.splice(+b.dataset.delete,1);setHistory(a);renderHistory()})}
$('historyBtn').onclick=()=>{$('historyModal').hidden=false;renderHistory()};$('historyCloseBtn').onclick=()=>{$('historyModal').hidden=true};$('historySnapshotBtn').onclick=()=>createSnapshot('Manuell');$('recoveryRestoreBtn').onclick=()=>{try{const a=JSON.parse(localStorage.getItem(AUTOSAVE_KEY)||'null');if(!a?.project)return status('Keine automatische Sicherung vorhanden');project=migrate(a.project);activeSlideId=project.slides[0].id;selected=null;selectedIds=new Set();render();status('Automatische Sicherung wiederhergestellt')}catch(e){status('Automatische Sicherung ist ungültig')}};
