function backgroundCssValue(value){const v=String(value||'');if(!v)return 'none';if(/^(linear-gradient|radial-gradient|conic-gradient)\(/i.test(v))return v;return `url(${JSON.stringify(v)})`}
function renderBackgroundPresets(){const box=$('backgroundPresets');if(!box)return;box.innerHTML='';const s=currentSlide();BACKGROUND_PRESETS.forEach(p=>{const b=document.createElement('button');b.type='button';b.className='backgroundPreset'+(s.backgroundPreset===p.id?' active':'');b.style.backgroundImage=backgroundCssValue(p.value)||'linear-gradient(135deg,#fff,#eee)';b.style.backgroundSize='cover';b.style.backgroundPosition='center';b.innerHTML=`<span>${p.name}</span>`;b.onclick=()=>{s.backgroundPreset=p.id;s.backgroundImage=p.value;s.backgroundFit=p.kind==='image'?'cover':(s.backgroundFit||'cover');s.backgroundOpacity=100;render();status(`Hintergrundvorlage „${p.name}“ angewendet`)};box.appendChild(b)})}
