function fitText(item){if(!item||!['text','button','ticker','input','panel','table'].includes(item.type))return;const text=String(item.text||' '),min=item.minFont||8,max=item.maxFont||160,pad=12;let size=max;const chars=Math.max(1,text.length);while(size>min){const charsPerLine=Math.max(1,Math.floor((item.w-pad)/(size*.56)));const lines=item.wrap===false?1:Math.ceil(chars/charsPerLine);if(lines*size*1.25<=item.h-pad)break;size--}item.font=Math.max(min,size)}
$('fitTextBtn').onclick=()=>{const i=currentItems().find(x=>x.id===selected);if(!i)return;i.textScaleMode='fit';fitText(i);render();status('Text optimal in den Rahmen eingepasst')};


function hexToRgba(hex,alpha=1){const h=String(hex||'#000000').replace('#','');const v=h.length===3?h.split('').map(c=>c+c).join(''):h;const n=parseInt(v,16)||0;return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${alpha})`}
