 if(item.effect==='sparkler'){el.classList.add('fx-sparkler');const core=document.createElement('span');core.className='sparkler-core';core.textContent='✦';el.appendChild(core);const layer=document.createElement('span');layer.className='sparkler-layer';const count=Math.min(160,Math.max(12,(item.density||5)*10));for(let n=0;n<count;n++){const p=document.createElement('i');p.className='spark';const ang=Math.random()*360,dist=25+Math.random()*Math.min(item.w,item.h)*.42;p.style.setProperty('--a',ang+'deg');p.style.setProperty('--d',dist+'px');p.style.setProperty('--s',(1+Math.random()*3)+'px');p.style.animationDuration=(.35+Math.random()*1.1+(10-(item.effectSpeed||5))*.05)+'s';p.style.animationDelay=(-Math.random()*2)+'s';layer.appendChild(p)}el.appendChild(layer);return}
 if(item.effect==='sun-rays'){el.classList.add('fx-sun-rays');el.textContent='☀';return}
