// V0.10.0 – Screenshot-/Foto-Import und lokale Layout-Rekonstruktion
let screenshotImage=null,screenshotDataUrl='',screenshotRegions=[],manualRegionStart=null;
function ensureSmartGuides(){if(!$('smartGuideV')){const v=document.createElement('i'),h=document.createElement('i');v.id='smartGuideV';h.id='smartGuideH';v.className='smart-guide v';h.className='smart-guide h';stage.append(v,h)}}
function hideSmartGuides(){['smartGuideV','smartGuideH'].forEach(id=>{const e=$(id);if(e)e.style.display='none'})}
function smartSnap(item,x,y){const tol=6,others=currentItems().filter(o=>o.id!==item.id);let nx=snap(x),ny=snap(y),gx=null,gy=null;const xs=[0,project.page.width/2,project.page.width],ys=[0,project.page.height/2,project.page.height];others.forEach(o=>{xs.push(o.x,o.x+o.w/2,o.x+o.w);ys.push(o.y,o.y+o.h/2,o.y+o.h)});const myX=[nx,nx+item.w/2,nx+item.w],myY=[ny,ny+item.h/2,ny+item.h];for(const target of xs)for(let k=0;k<3;k++)if(Math.abs(myX[k]-target)<=tol){nx+=target-myX[k];gx=target;break}for(const target of ys)for(let k=0;k<3;k++)if(Math.abs(myY[k]-target)<=tol){ny+=target-myY[k];gy=target;break}ensureSmartGuides();const v=$('smartGuideV'),h=$('smartGuideH');if(gx!==null){v.style.left=gx+'px';v.style.display='block'}else v.style.display='none';if(gy!==null){h.style.top=gy+'px';h.style.display='block'}else h.style.display='none';return{x:Math.max(0,nx),y:Math.max(0,ny)}}
function openScreenshotModal(){$('screenshotModal').hidden=false}
function closeScreenshotModal(){$('screenshotModal').hidden=true}
function loadScreenshotFile(file){if(!file)return;const r=new FileReader();r.onload=()=>{screenshotDataUrl=String(r.result);const img=new Image();img.onload=()=>{screenshotImage=img;drawScreenshot();screenshotRegions=[];renderScreenshotRegions();openScreenshotModal();status('Screenshot geladen')};img.src=screenshotDataUrl};r.readAsDataURL(file)}
function drawScreenshot(){const c=$('screenshotCanvas'),wrap=$('screenshotEmpty');if(!screenshotImage){wrap.hidden=false;return}wrap.hidden=true;const maxW=1100,maxH=760,scale=Math.min(1,maxW/screenshotImage.width,maxH/screenshotImage.height);c.width=Math.round(screenshotImage.width*scale);c.height=Math.round(screenshotImage.height*scale);c.dataset.scale=String(scale);c.getContext('2d').drawImage(screenshotImage,0,0,c.width,c.height);drawRegionOverlays()}
function drawRegionOverlays(){const c=$('screenshotCanvas'),ctx=c.getContext('2d');if(screenshotImage){const sc=Number(c.dataset.scale||1);ctx.drawImage(screenshotImage,0,0,c.width,c.height);ctx.save();ctx.lineWidth=2;ctx.font='11px sans-serif';screenshotRegions.forEach((r,n)=>{ctx.strokeStyle=r.enabled===false?'#94a3b8':'#ff2c8b';ctx.setLineDash(r.manual?[6,3]:[]);ctx.strokeRect(r.x*sc,r.y*sc,r.w*sc,r.h*sc);ctx.fillStyle='#ff2c8b';ctx.fillRect(r.x*sc,r.y*sc,Math.min(110,r.w*sc),16);ctx.fillStyle='#fff';ctx.fillText((n+1)+' '+r.type,r.x*sc+3,r.y*sc+12)});ctx.restore()}}
function colorDistance(a,b){return Math.abs(a[0]-b[0])+Math.abs(a[1]-b[1])+Math.abs(a[2]-b[2])}
function detectScreenshotRegions(){if(!screenshotImage)return status('Bitte zuerst einen Screenshot laden');const sens=Number($('screenshotSensitivity').value),minSize=Number($('screenshotMinSize').value);const work=document.createElement('canvas'),max=320,scale=Math.min(1,max/screenshotImage.width,max/screenshotImage.height);work.width=Math.max(1,Math.round(screenshotImage.width*scale));work.height=Math.max(1,Math.round(screenshotImage.height*scale));const ctx=work.getContext('2d',{willReadFrequently:true});ctx.drawImage(screenshotImage,0,0,work.width,work.height);const data=ctx.getImageData(0,0,work.width,work.height).data,step=4,cols=Math.ceil(work.width/step),rows=Math.ceil(work.height/step),active=new Uint8Array(cols*rows);function pix(x,y){const p=(Math.min(work.height-1,y)*work.width+Math.min(work.width-1,x))*4;return[data[p],data[p+1],data[p+2]]}for(let gy=0;gy<rows;gy++)for(let gx=0;gx<cols;gx++){const x=gx*step,y=gy*step,c=pix(x,y),r=pix(Math.min(work.width-1,x+step),y),d=pix(x,Math.min(work.height-1,y+step));if(Math.max(colorDistance(c,r),colorDistance(c,d))>sens*3.2)active[gy*cols+gx]=1}const seen=new Uint8Array(active.length),regions=[];for(let i=0;i<active.length;i++){if(!active[i]||seen[i])continue;let q=[i],head=0,minx=cols,miny=rows,maxx=0,maxy=0,count=0;seen[i]=1;while(head<q.length){const p=q[head++],x=p%cols,y=(p/cols)|0;minx=Math.min(minx,x);maxx=Math.max(maxx,x);miny=Math.min(miny,y);maxy=Math.max(maxy,y);count++;for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy,ni=ny*cols+nx;if(nx>=0&&ny>=0&&nx<cols&&ny<rows&&active[ni]&&!seen[ni]){seen[ni]=1;q.push(ni)}}}const x=minx*step/scale,y=miny*step/scale,w=(maxx-minx+1)*step/scale,h=(maxy-miny+1)*step/scale;if(w>=minSize&&h>=Math.max(12,minSize*.45)&&w*h< screenshotImage.width*screenshotImage.height*.75&&count>2){regions.push(makeDetectedRegion(x,y,w,h))}}screenshotRegions=mergeDetectedRegions(regions).slice(0,80);renderScreenshotRegions();drawRegionOverlays();status(`${screenshotRegions.length} Bereiche erkannt`)}
function makeDetectedRegion(x,y,w,h){const ratio=w/Math.max(1,h);let type=h<42&&w>65?'button':h<30&&w>45?'text':ratio>4?'text':w>180&&h>100?'panel':'image';return{x:Math.round(x),y:Math.round(y),w:Math.round(w),h:Math.round(h),type,enabled:true,manual:false}}
function overlaps(a,b){const ix=Math.max(0,Math.min(a.x+a.w,b.x+b.w)-Math.max(a.x,b.x)),iy=Math.max(0,Math.min(a.y+a.h,b.y+b.h)-Math.max(a.y,b.y));return ix*iy>Math.min(a.w*a.h,b.w*b.h)*.55}
function mergeDetectedRegions(regs){const out=[];regs.sort((a,b)=>b.w*b.h-a.w*a.h).forEach(r=>{if(!out.some(o=>overlaps(o,r)))out.push(r)});return out.sort((a,b)=>a.y-b.y||a.x-b.x)}
function renderScreenshotRegions(){const box=$('screenshotRegions');box.innerHTML='';screenshotRegions.forEach((r,n)=>{const row=document.createElement('div');row.className='screenshotRegion';const check=document.createElement('input');check.type='checkbox';check.checked=r.enabled!==false;check.onchange=()=>{r.enabled=check.checked;drawRegionOverlays()};const info=document.createElement('span');info.textContent=`${n+1}: ${r.w}×${r.h} bei ${r.x}/${r.y}`;const sel=document.createElement('select');[['button','Button'],['text','Text'],['input','Eingabefeld'],['panel','Fläche/Rahmen'],['image','Grafik/Bildausschnitt'],['rectangle','Rechteck']].forEach(([v,l])=>{const o=document.createElement('option');o.value=v;o.textContent=l;sel.appendChild(o)});sel.value=r.type;sel.onchange=()=>{r.type=sel.value;drawRegionOverlays()};row.append(check,info,sel);box.appendChild(row)})}
function cropRegionDataUrl(r){const c=document.createElement('canvas');c.width=Math.max(1,r.w);c.height=Math.max(1,r.h);c.getContext('2d').drawImage(screenshotImage,r.x,r.y,r.w,r.h,0,0,r.w,r.h);return c.toDataURL('image/png')}
function screenshotAsReference(){if(!screenshotDataUrl)return;const s=currentSlide();s.backgroundImage=screenshotDataUrl;s.backgroundFit='stretch';s.backgroundOpacity=45;project.page.width=screenshotImage.width;project.page.height=screenshotImage.height;render();status('Screenshot als halbtransparente Vorlage gesetzt')}
function importScreenshotObjects(){if(!screenshotImage)return;project.page.width=screenshotImage.width;project.page.height=screenshotImage.height;const added=[];screenshotRegions.filter(r=>r.enabled!==false).forEach((r,n)=>{addItem(r.type,r.x,r.y);const i=currentItems().find(x=>x.id===selected);i.w=Math.max(20,r.w);i.h=Math.max(20,r.h);i.name=`Erkannt_${n+1}_${r.type}`;if(r.type==='image'){i.src=cropRegionDataUrl(r);i.text=''}else if(r.type==='text'){i.text='Erkannter Text';i.bg='#ffffff';i.opacity=25}else if(r.type==='button'){i.text='Button';i.bg='#e5e7eb'}else if(r.type==='input'){i.text='Eingabefeld'}else{i.text='';i.bg='#f8fafc';i.opacity=45}added.push(i.id)});if($('screenshotKeepReference').checked){const ref={id:uid('el'),type:'image',name:'Screenshot Referenz (gesperrt)',text:'',x:0,y:0,w:project.page.width,h:project.page.height,font:16,color:'#000000',bg:'#ffffff',align:'left',bold:false,src:screenshotDataUrl,fit:'stretch',opacity:22,locked:true,reference:true};currentItems().unshift(ref)}closeScreenshotModal();selectedIds=new Set(added);selected=added.at(-1)||null;render();status(`${added.length} bearbeitbare Objekte übernommen`)}
$('screenshotImportBtn')?.addEventListener('click',openScreenshotModal);$('screenshotFile')?.addEventListener('change',e=>loadScreenshotFile(e.target.files?.[0]));$('screenshotCloseBtn')?.addEventListener('click',closeScreenshotModal);$('screenshotDetectBtn')?.addEventListener('click',detectScreenshotRegions);$('screenshotBackgroundBtn')?.addEventListener('click',screenshotAsReference);$('screenshotImportObjectsBtn')?.addEventListener('click',importScreenshotObjects);$('screenshotSensitivity')?.addEventListener('input',()=>{$('screenshotSensitivityOut').value=$('screenshotSensitivity').value});$('screenshotMinSize')?.addEventListener('input',()=>{$('screenshotMinSizeOut').value=$('screenshotMinSize').value+' px'});
$('screenshotCanvas')?.addEventListener('pointerdown',e=>{if(!screenshotImage)return;const r=e.currentTarget.getBoundingClientRect(),sc=Number(e.currentTarget.dataset.scale||1);manualRegionStart={x:(e.clientX-r.left)/sc,y:(e.clientY-r.top)/sc}});$('screenshotCanvas')?.addEventListener('pointerup',e=>{if(!manualRegionStart)return;const c=e.currentTarget,r=c.getBoundingClientRect(),sc=Number(c.dataset.scale||1),ex=(e.clientX-r.left)/sc,ey=(e.clientY-r.top)/sc,x=Math.min(manualRegionStart.x,ex),y=Math.min(manualRegionStart.y,ey),w=Math.abs(ex-manualRegionStart.x),h=Math.abs(ey-manualRegionStart.y);manualRegionStart=null;if(w>8&&h>8){const region=makeDetectedRegion(x,y,w,h);region.manual=true;screenshotRegions.push(region);renderScreenshotRegions();drawRegionOverlays()}});

function status(t){$('status').textContent=t}function escapeHtml(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}


