function ensureTimelineData(){project.version='0.21.0';project.slides.forEach(s=>{s.timeline=Array.isArray(s.timeline)?s.timeline:[];s.timelineDuration=Number(s.timelineDuration||s.duration||10);s.items.forEach(i=>{i.events=Array.isArray(i.events)?i.events:[]})})}
function timelineSnap(v){const g=Number($('timelineGrid')?.value||.5);return Math.max(0,Math.round(Number(v||0)/g)*g)}
function timelineLabel(c){const item=currentItems().find(i=>i.id===c.targetId);return c.type==='object'?(item?.name||'Objekt'):c.type==='effect'?'Effekt: '+(item?.effect||''):c.type==='ticker'?'Laufschrift':c.type==='weather'?'Wetter aktualisieren':c.type==='audio'?'Audio':c.type==='video'?'Video':'Aktion'}
function renderTimeline(){ensureTimelineData();const s=currentSlide(),duration=Math.max(1,Number(s.timelineDuration||s.duration||10));$('timelineDuration').value=duration;const width=Math.max(900,duration*80),scale=$('timelineScale'),tracks=$('timelineTracks'),names=$('timelineTrackNames');scale.style.width=tracks.style.width=width+'px';scale.innerHTML='';for(let t=0;t<=duration;t+=Math.max(1,Math.ceil(duration/20))){const tick=document.createElement('span');tick.className='timelineTick';tick.style.left=(t/duration*100)+'%';tick.textContent=t+' s';scale.appendChild(tick)}tracks.innerHTML='';names.innerHTML='';s.timeline.forEach((c,n)=>{const name=document.createElement('div');name.className='timelineTrackName';name.textContent=`${n+1}. ${timelineLabel(c)}`;names.appendChild(name);const track=document.createElement('div');track.className='timelineTrack';const cue=document.createElement('div');cue.className='timelineCue'+(timelineSelectedCue===c.id?' selected':'');cue.dataset.type=c.type;cue.dataset.id=c.id;cue.style.left=(c.start/duration*100)+'%';cue.style.width=(Math.max(.1,c.duration)/duration*100)+'%';cue.textContent=`${timelineLabel(c)} · ${c.start.toFixed(1)}–${(c.start+c.duration).toFixed(1)} s`;const resize=document.createElement('i');resize.className='timelineResize';cue.appendChild(resize);cue.onclick=e=>{e.stopPropagation();timelineSelectedCue=c.id;$('timelineCueType').value=c.type;$('timelineStart').value=c.start;$('timelineCueDuration').value=c.duration;$('timelineSource').value=c.source||c.action||'';renderTimeline()};cue.onpointerdown=e=>timelineCuePointerDown(e,c,duration,resize===e.target);track.appendChild(cue);tracks.appendChild(track)});$('timelinePlayhead').style.left='0px';$('timelineTime').textContent='0,0 s'}
