function openTimeline(){ensureTimelineData();renderTimeline();$('timelineModal').hidden=false}
function stopTimeline(){clearInterval(timelineTimer);timelineTimer=null;timelineAudio.forEach(a=>{try{a.pause()}catch{}});timelineAudio=[];document.body.classList.remove('timeline-playing');stage.querySelectorAll('.designer-item').forEach(el=>el.classList.remove('timeline-hidden'));$('timelinePlayhead').style.left='0px';$('timelineTime').textContent='0,0 s'}
function applyTimelineAt(time){const s=currentSlide(),duration=Math.max(1,Number(s.timelineDuration||10)),width=$('timelineTracks').getBoundingClientRect().width;$('timelinePlayhead').style.left=(time/duration*width)+'px';$('timelineTime').textContent=time.toFixed(1)+' s';const objectCues=s.timeline.filter(c=>['object','effect','ticker'].includes(c.type));const targeted=new Set(objectCues.map(c=>c.targetId));stage.querySelectorAll('.designer-item').forEach(el=>{if(!targeted.has(el.dataset.id))return;const active=objectCues.some(c=>c.targetId===el.dataset.id&&time>=c.start&&time<=c.start+c.duration);el.classList.toggle('timeline-hidden',!active)});s.timeline.filter(c=>Math.abs(time-c.start)<.08&&!c._fired).forEach(c=>{c._fired=true;if(c.type==='audio'&&c.source){const a=new Audio(c.source);timelineAudio.push(a);a.play().catch(()=>status('Audio konnte im Browser nicht automatisch gestartet werden'))}if(c.type==='weather'){const it=currentItems().find(i=>i.id===c.targetId);if(it?.type==='weather')render()}if(c.type==='action'&&c.action==='next-slide')status('Timeline-Aktion: nächste Folie')})}
