// V0.22.1 – PowerPoint Import und TV-Ausgabeprofil
function xmlChildren(node,name){return [...node.getElementsByTagName('*')].filter(n=>n.localName===name)}
function xmlFirst(node,name){return xmlChildren(node,name)[0]||null}
function emu(v){return Number(v||0)/914400*96}
function fileToDataUrl(blob){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(blob)})}
async function importPptx(file){if(!window.JSZip)throw new Error('ZIP-Bibliothek fehlt');status('PowerPoint wird analysiert …');const zip=await JSZip.loadAsync(file);const parser=new DOMParser();const presFile=zip.file('ppt/presentation.xml');if(!presFile)throw new Error('Keine gültige PPTX-Datei');const pres=parser.parseFromString(await presFile.async('text'),'application/xml');const sz=xmlFirst(pres,'sldSz');const srcW=Number(sz?.getAttribute('cx')||12192000),srcH=Number(sz?.getAttribute('cy')||6858000);const targetW=project.page.width,targetH=project.page.height;const sx=targetW/(srcW/914400*96),sy=targetH/(srcH/914400*96);const slideNames=Object.keys(zip.files).filter(n=>/^ppt\/slides\/slide\d+\.xml$/.test(n)).sort((a,b)=>Number(a.match(/\d+/)[0])-Number(b.match(/\d+/)[0]));const imported=[];
 for(let si=0;si<slideNames.length;si++){const name=slideNames[si],doc=parser.parseFromString(await zip.file(name).async('text'),'application/xml');const relName=name.replace('ppt/slides/','ppt/slides/_rels/')+'.rels';let relMap={};if(zip.file(relName)){const rd=parser.parseFromString(await zip.file(relName).async('text'),'application/xml');xmlChildren(rd,'Relationship').forEach(r=>relMap[r.getAttribute('Id')]=r.getAttribute('Target'))}const slide=newSlide(si+1);slide.name=`PPT Folie ${si+1}`;const shapes=[...xmlChildren(doc,'sp')];for(const sp of shapes){const texts=xmlChildren(sp,'t').map(n=>n.textContent).join(' ').trim();const xfrm=xmlFirst(sp,'xfrm'),off=xfrm?xmlFirst(xfrm,'off'):null,ext=xfrm?xmlFirst(xfrm,'ext'):null;if(!texts&&!xfrm)continue;const item={...defaults.text,id:uid('el'),type:'text',name:'PPT_Text',text:texts||'',x:Math.round(emu(off?.getAttribute('x'))*sx),y:Math.round(emu(off?.getAttribute('y'))*sy),w:Math.max(40,Math.round(emu(ext?.getAttribute('cx'))*sx)),h:Math.max(28,Math.round(emu(ext?.getAttribute('cy'))*sy)),font:Math.max(12,Math.round(18*Math.min(sx,sy))),color:'#111827',bg:'transparent',align:'left',bold:false,opacity:100,rotation:0,wrap:true};slide.items.push(item)}
 for(const pic of xmlChildren(doc,'pic')){const blip=xmlFirst(pic,'blip');const rid=blip?.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','embed')||blip?.getAttribute('r:embed');const target=relMap[rid];const xfrm=xmlFirst(pic,'xfrm'),off=xfrm?xmlFirst(xfrm,'off'):null,ext=xfrm?xmlFirst(xfrm,'ext'):null;if(!target||!xfrm)continue;const mediaPath='ppt/'+target.replace(/^\.\.\//,'');const zf=zip.file(mediaPath);if(!zf)continue;const src=await fileToDataUrl(await zf.async('blob'));slide.items.push({id:uid('el'),type:'image',name:'PPT_Bild',text:'',src,fit:'contain',x:Math.round(emu(off?.getAttribute('x'))*sx),y:Math.round(emu(off?.getAttribute('y'))*sy),w:Math.max(40,Math.round(emu(ext?.getAttribute('cx'))*sx)),h:Math.max(40,Math.round(emu(ext?.getAttribute('cy'))*sy)),font:16,color:'#111',bg:'transparent',align:'center',bold:false,opacity:100,rotation:0})}imported.push(slide)}
 if(!imported.length)throw new Error('Keine Folien gefunden');project.slides=imported;project.mode='presentation';project.name=file.name.replace(/\.pptx$/i,'');project.importInfo={source:'PowerPoint',file:file.name,importedAt:new Date().toISOString(),slides:imported.length};activeSlideId=imported[0].id;selected=null;selectedIds.clear();render();createSnapshot('PowerPoint-Import');status(`${imported.length} PowerPoint-Folien importiert – nicht unterstützte Spezialeffekte bitte prüfen`)}
$('pptxImportFile').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{await importPptx(f)}catch(err){console.error(err);status('PowerPoint-Import fehlgeschlagen: '+err.message)}finally{e.target.value=''}};
function tvAspectNumbers(v){const [a,b]=v.split(':').map(Number);return[a,b]}
function updateTvMetrics(){const inches=Number($('tvInches').value),[aw,ah]=tvAspectNumbers($('tvAspect').value),diagCm=inches*2.54,k=Math.sqrt(aw*aw+ah*ah),w=diagCm*aw/k,h=diagCm*ah/k,[pxw,pxh]=$('tvResolution').value.split('x').map(Number),safe=Number($('tvSafeZone').value);$('tvSafeZoneOut').value=safe+' %';$('tvMetrics').innerHTML=`<strong>${inches} Zoll · ${$('tvAspect').value}</strong><br>Bildfläche ca. ${w.toFixed(1)} × ${h.toFixed(1)} cm<br>Zielauflösung ${pxw} × ${pxh} px<br>Sicherer Inhaltsbereich ${Math.round(pxw*(1-safe/50))} × ${Math.round(pxh*(1-safe/50))} px`;return{inches,aw,ah,w,h,pxw,pxh,safe}}
function auditTv(){const m=updateTvMetrics(),issues=[];project.slides.forEach((s,si)=>s.items.forEach(i=>{if((i.font||16)<28)issues.push(`Folie ${si+1}: ${i.name||i.type} Schrift ${i.font||16}px`);if(i.x<m.pxw*m.safe/100||i.y<m.pxh*m.safe/100||i.x+i.w>m.pxw*(1-m.safe/100)||i.y+i.h>m.pxh*(1-m.safe/100))issues.push(`Folie ${si+1}: ${i.name||i.type} nahe am Rand`)}));$('tvAudit').innerHTML=issues.length?`<strong>${issues.length} Hinweise</strong><br>${issues.slice(0,12).map(escapeHtml).join('<br>')}`:'<strong>Keine kritischen TV-Hinweise.</strong>';return issues}
$('tvOptimizeBtn').onclick=()=>{$('tvOptimizeModal').hidden=false;updateTvMetrics();auditTv()};$('tvOptimizeClose').onclick=()=>$('tvOptimizeModal').hidden=true;['tvInches','tvAspect','tvResolution','tvSafeZone'].forEach(id=>$(id).addEventListener('input',()=>{updateTvMetrics();auditTv()}));$('tvOptimizeAudit').onclick=auditTv;
$('tvOptimizeApply').onclick=()=>{const m=updateTvMetrics(),oldW=project.page.width,oldH=project.page.height,sx=m.pxw/oldW,sy=m.pxh/oldH;if($('tvScaleObjects').checked)project.slides.forEach(s=>s.items.forEach(i=>{i.x=Math.round(i.x*sx);i.y=Math.round(i.y*sy);i.w=Math.round(i.w*sx);i.h=Math.round(i.h*sy);i.font=Math.round((i.font||16)*Math.min(sx,sy));if($('tvImproveReadability').checked)i.font=Math.max(28,i.font)}));project.page.width=m.pxw;project.page.height=m.pxh;project.mode='tv';project.tvProfile={inches:m.inches,aspect:$('tvAspect').value,resolution:$('tvResolution').value,safeZone:m.safe,safeGuides:$('tvEnableSafeGuides').checked,physicalWidthCm:m.w,physicalHeightCm:m.h};document.body.classList.toggle('showTvSafeGuides',!!project.tvProfile.safeGuides);$('tvOptimizeModal').hidden=true;render();createSnapshot(`TV ${m.inches} Zoll`);status(`Für ${m.inches}-Zoll-TV optimiert (${m.pxw} × ${m.pxh})`)};

