function interpolate(a,b,t){return Number(a)+(Number(b)-Number(a))*t}
function keyframeState(c,local){const frames=(c.keyframes||[]).slice().sort((a,b)=>a.time-b.time);if(!frames.length)return null;if(local<=frames[0].time)return frames[0];if(local>=frames.at(-1).time)return frames.at(-1);let a=frames[0],b=frames.at(-1);for(let n=0;n<frames.length-1;n++){if(local>=frames[n].time&&local<=frames[n+1].time){a=frames[n];b=frames[n+1];break}}const t=(local-a.time)/Math.max(.001,b.time-a.time);return {x:interpolate(a.x,b.x,t),y:interpolate(a.y,b.y,t),w:interpolate(a.w,b.w,t),h:interpolate(a.h,b.h,t),rotation:interpolate(a.rotation||0,b.rotation||0,t),opacity:interpolate(a.opacity??100,b.opacity??100,t)}}
function applyCueAnimation(el,c,progress){const p=Math.max(0,Math.min(1,progress)),enter=Math.min(1,p*4),exit=Math.min(1,(1-p)*4),vis=Math.min(enter,exit);let extra='';let op=1;if(c.animation==='fade')op=vis;if(c.animation==='slide-left')extra=` translateX(${(1-enter)*-80}px)`;if(c.animation==='slide-right')extra=` translateX(${(1-enter)*80}px)`;if(c.animation==='slide-up')extra=` translateY(${(1-enter)*80}px)`;if(c.animation==='zoom')extra=` scale(${.5+.5*enter})`;if(c.animation==='rotate')extra=` rotate(${(1-enter)*-180}deg)`;if(c.animation==='pulse')extra=` scale(${1+Math.sin(p*Math.PI*6)*.08})`;el.style.transitionTimingFunction=c.easing||'ease';el.style.opacity=String(op);el.style.setProperty('--timeline-extra-transform',extra)}
