applyTimelineAt=function(time){applyTimelineAtV012(time);const s=currentSlide();s.timeline.filter(c=>['object','effect','ticker'].includes(c.type)).forEach(c=>{const el=stage.querySelector(`[data-id="${c.targetId}"]`);if(!el)return;const active=time>=c.start&&time<=c.start+c.duration;if(!active)return;el.classList.add('timeline-animated');const local=time-c.start,state=keyframeState(c,local),item=currentItems().find(i=>i.id===c.targetId);if(state){el.style.left=state.x+'px';el.style.top=state.y+'px';el.style.width=state.w+'px';el.style.height=state.h+'px';el.style.opacity=String((state.opacity??100)/100);el.style.transform=`rotate(${state.rotation||0}deg) var(--timeline-extra-transform, )`}else if(item){el.style.transform=`rotate(${item.rotation||0}deg) var(--timeline-extra-transform, )`;applyCueAnimation(el,c,local/Math.max(.1,c.duration))}})}
