async function ladeStandardpraesentationBeimErstenStart(){
  // Nur beim ALLERERSTEN Öffnen (noch kein lokal gespeichertes Projekt vorhanden) - eine bereits
  // begonnene Arbeit des Nutzers wird dadurch nie überschrieben.
  if(localStorage.getItem('fs3.visualDesigner.project'))return;
  try{
    const antwort=await fetch('assets/kasse-presentation/KC_Weihnachtsmarkt_2026_Designer.json');
    if(!antwort.ok)return;
    const daten=await antwort.json();
    if(!Array.isArray(daten.slides)||!daten.slides.length)return;
    project=migrate(daten);
    activeSlideId=project.slides[0].id;
    localStorage.setItem('fs3.visualDesigner.project',JSON.stringify(project));
    status(`Vorbereitete Präsentation geladen (${project.slides.length} Folien)`);
  }catch(e){ /* Datei nicht erreichbar - bleibt bei der leeren Standardfolie, kein Fehler sichtbar */ }
}

