// V0.23.0 – PowerPoint-Migrationsassistent und TV-Paketexport
function tvProfileSummary(){
  const p=project.tvProfile||{};
  return {inches:Number(p.inches||43),aspect:p.aspect||'16:9',resolution:p.resolution||'fullhd',width:Number(project.page.width||1920),height:Number(project.page.height||1080),safeZone:Number(p.safeZone||5)};
}
function buildTvReadme(profile){return `FRAMEWORK STUDIO TV-PAKET\n\nProjekt: ${project.name||'Präsentation'}\nZielgerät: ${profile.inches} Zoll, ${profile.aspect}\nAuflösung: ${profile.width} x ${profile.height}\n\nSTART AM PC / NOTEBOOK\n1. Ordner vollständig entpacken.\n2. START_TV_PLAYER.html im Browser öffnen.\n3. Vollbild aktivieren (F11).\n\nUSB-STICK / SMART-TV\n- Das Paket ist offline und benötigt kein Internet.\n- Viele Fernseher öffnen lokale HTML-Dateien nicht direkt. In diesem Fall den Stick an einen Mini-PC, Notebook oder kompatiblen TV-Browser anschließen.\n\nAMAZON FIRE TV\n1. Paket auf einen lokalen Webserver, NAS oder Mini-PC kopieren.\n2. Im Fire-TV-Browser die Adresse der START_TV_PLAYER.html öffnen.\n3. Browser im Vollbild-/Kioskmodus betreiben.\n\nWICHTIG\n- Für maximale Kompatibilität ist der HTML-Player selbstständig und enthält das Projekt eingebettet.\n- Dynamische Wetter-/PC-Manager-/Dienstplandaten benötigen später den jeweiligen Adapter oder eine lokale Datendatei.\n- Reine Fernseher unterstützen je nach Hersteller HTML, Animationen und lokale Dateien unterschiedlich.\n`;}
async function exportTvPackage(){
  if(!window.JSZip){status('ZIP-Bibliothek fehlt');return}
  const profile=tvProfileSummary();
  if(project.mode!=='tv')status('Hinweis: Projekt wird als TV-Paket exportiert; vorher TV vorbereiten wird empfohlen');
  const zip=new JSZip();
  const player=buildStandaloneProgram().replace('</title>',`</title><meta name="fs-tv-profile" content="${profile.inches} Zoll ${profile.aspect} ${profile.width}x${profile.height}">`);
  zip.file('START_TV_PLAYER.html',player);
  zip.file('project/project.fsproj.json',JSON.stringify({schema:'framework-studio.tv-project',schemaVersion:'1.0.0',createdAt:new Date().toISOString(),tvProfile:profile,project},null,2));
  zip.file('README_START.txt',buildTvReadme(profile));
  zip.file('manifest.json',JSON.stringify({name:project.name||'Präsentation',version:'0.24.0',type:'offline-tv-package',entry:'START_TV_PLAYER.html',tvProfile:profile,capabilities:['offline','autoplay-slides','fullscreen','loop','embedded-assets'],sourceImport:project.importInfo||null},null,2));
  zip.file('FIRE_TV_HINWEISE.html',`<!doctype html><meta charset="utf-8"><title>Fire TV Hinweise</title><style>body{font:18px Arial;max-width:900px;margin:40px auto;line-height:1.5}code{background:#eee;padding:3px 6px}</style><h1>Fire TV / Android TV</h1><p>Dieses Paket ist ein Offline-HTML-Player. Öffne <code>START_TV_PLAYER.html</code> in einem kompatiblen Browser. Da Fire TV lokale Dateien nicht zuverlässig direkt öffnet, empfiehlt sich ein lokaler Webserver/NAS oder ein Mini-PC am Fernseher.</p><p>Für einen USB-Stick direkt am Fernseher hängt die Unterstützung vom TV-Hersteller ab. Viele Geräte spielen nur Video/Bilddateien, aber kein HTML.</p>`);
  const blob=await zip.generateAsync({type:'blob',compression:'DEFLATE',compressionOptions:{level:6}});
  const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=safeFileName(project.name||'praesentation')+'_TV_Paket.zip';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);status(`TV-Paket für ${profile.inches} Zoll exportiert`);
}
