// V0.24.0 – Medienexport: PNG-Sequenz, WebM und MP4-Konvertierungspaket
function mediaExportEstimate(){
 const slides=project.slides||[],fps=Number($('mediaExportFps')?.value||25),loop=$('mediaExportLoop')?.checked?2:1;
 const seconds=slides.reduce((n,s)=>n+Number(s.duration||10),0)*loop;
 const frames=Math.max(1,Math.ceil(seconds*fps));
 const resolution=$('mediaExportResolution')?.value||'1920x1080';
 if($('mediaExportEstimate')) $('mediaExportEstimate').innerHTML=`<strong>${slides.length} Folien</strong><br>${seconds.toFixed(1)} Sekunden · ca. ${frames} Videoframes<br>${resolution} · ${fps} fps`;
 return {seconds,frames,fps,resolution};
}
function mediaStatus(text,pct){if($('mediaExportStatus'))$('mediaExportStatus').textContent=text;if($('mediaExportProgress')&&pct!=null)$('mediaExportProgress').value=pct;status(text)}
async function inlineCloneForCapture(source){
 const clone=source.cloneNode(true),srcNodes=[source,...source.querySelectorAll('*')],dstNodes=[clone,...clone.querySelectorAll('*')];
 for(let i=0;i<srcNodes.length;i++){
  const src=srcNodes[i],dst=dstNodes[i],cs=getComputedStyle(src);
  dst.setAttribute('style',Array.from(cs).map(k=>`${k}:${cs.getPropertyValue(k)};`).join(''));
  if(src.tagName==='CANVAS'){
   const img=document.createElement('img');try{img.src=src.toDataURL('image/png')}catch{}img.setAttribute('style',dst.getAttribute('style')||'');dst.replaceWith(img);
  }
 }
 clone.querySelectorAll('.resizeHandle,.selectionOutline,.guide,.safeZoneGuide').forEach(n=>n.remove());
 return clone;
}
async function safeCanvasImage(src){
 if(!src)return null;try{
  let url=src,cleanup=null;
  if(/^https?:/i.test(src)){const r=await fetch(src,{mode:'cors'});if(!r.ok)throw new Error('HTTP '+r.status);url=URL.createObjectURL(await r.blob());cleanup=()=>URL.revokeObjectURL(url)}
  const img=await new Promise((res,rej)=>{const x=new Image();x.onload=()=>res(x);x.onerror=rej;x.src=url});if(cleanup)setTimeout(cleanup,1000);return img
 }catch(err){console.warn('Bild beim Medienexport übersprungen',src,err);return null}
}
function wrapCanvasText(ctx,text,maxWidth){const words=String(text||'').split(/\s+/),lines=[];let line='';for(const word of words){const t=line?line+' '+word:word;if(ctx.measureText(t).width>maxWidth&&line){lines.push(line);line=word}else line=t}if(line)lines.push(line);return lines}
