 const drawShape=(it)=>{const x=it.x*sx,y=it.y*sy,w=it.w*sx,h=it.h*sy;ctx.save();ctx.globalAlpha=(it.opacity??100)/100;ctx.translate(x+w/2,y+h/2);ctx.rotate((it.rotation||0)*Math.PI/180);ctx.translate(-w/2,-h/2);ctx.fillStyle=it.fill||it.bg||'#ffffff';ctx.strokeStyle=it.stroke||'#1c2430';ctx.lineWidth=(it.strokeWidth||0)*Math.min(sx,sy);if(it.shadowEnabled){ctx.shadowColor=it.shadowColor||'#000';ctx.shadowBlur=(it.shadowBlur||10)*Math.min(sx,sy);ctx.shadowOffsetX=(it.shadowX||0)*sx;ctx.shadowOffsetY=(it.shadowY||0)*sy}
  ctx.beginPath();if(it.type==='ellipse')ctx.ellipse(w/2,h/2,w/2,h/2,0,0,Math.PI*2);else if(it.type==='triangle'){ctx.moveTo(w/2,0);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.closePath()}else if(it.type==='line'||it.type==='arrow'){ctx.moveTo(0,h/2);ctx.lineTo(w,h/2)}else{const r=Math.min(Number(it.radius||0)*Math.min(sx,sy),w/2,h/2);if(ctx.roundRect)ctx.roundRect(0,0,w,h,r);else ctx.rect(0,0,w,h)}if(it.type!=='line'&&it.type!=='arrow')ctx.fill();if((it.strokeWidth||0)>0||it.type==='line'||it.type==='arrow')ctx.stroke();if(it.type==='arrow'){ctx.beginPath();ctx.moveTo(w,h/2);ctx.lineTo(w-14*Math.min(sx,sy),h/2-9*Math.min(sx,sy));ctx.lineTo(w-14*Math.min(sx,sy),h/2+9*Math.min(sx,sy));ctx.closePath();ctx.fillStyle=it.stroke||'#1c2430';ctx.fill()}ctx.restore()};
