// V0.26.0 – Ebenen-, Sperr- und Ausrichtungsstudio
function reorderLayer(sourceId,targetId){if(sourceId===targetId)return;const items=currentItems(),from=items.findIndex(x=>x.id===sourceId),to=items.findIndex(x=>x.id===targetId);if(from<0||to<0)return;const [m]=items.splice(from,1);items.splice(to,0,m);selected=sourceId;render();status('Ebene verschoben')}
function selectedLayerItems(){const ids=new Set(selectedIds);if(selected)ids.add(selected);return currentItems().filter(i=>ids.has(i.id)&&!i.locked)}
function alignSelection(kind){const items=selectedLayerItems();if(items.length<2)return status('Mindestens zwei entsperrte Objekte auswählen');const minX=Math.min(...items.map(i=>i.x)),maxX=Math.max(...items.map(i=>i.x+i.w)),minY=Math.min(...items.map(i=>i.y)),maxY=Math.max(...items.map(i=>i.y+i.h));items.forEach(i=>{if(kind==='left')i.x=minX;if(kind==='center')i.x=Math.round((minX+maxX-i.w)/2);if(kind==='right')i.x=maxX-i.w;if(kind==='top')i.y=minY;if(kind==='middle')i.y=Math.round((minY+maxY-i.h)/2);if(kind==='bottom')i.y=maxY-i.h});render();status('Objekte ausgerichtet')}
function distributeSelection(axis){const items=selectedLayerItems().sort((a,b)=>axis==='h'?a.x-b.x:a.y-b.y);if(items.length<3)return status('Mindestens drei entsperrte Objekte auswählen');if(axis==='h'){const first=items[0].x,last=items.at(-1).x+items.at(-1).w,total=items.reduce((s,i)=>s+i.w,0),gap=(last-first-total)/(items.length-1);let x=first;items.forEach(i=>{i.x=Math.round(x);x+=i.w+gap})}else{const first=items[0].y,last=items.at(-1).y+items.at(-1).h,total=items.reduce((s,i)=>s+i.h,0),gap=(last-first-total)/(items.length-1);let y=first;items.forEach(i=>{i.y=Math.round(y);y+=i.h+gap})}render();status('Abstände gleichmäßig verteilt')}
function equalizeSelection(axis){const items=selectedLayerItems();if(items.length<2)return status('Mindestens zwei entsperrte Objekte auswählen');const ref=currentItems().find(i=>i.id===selected)||items[0];items.forEach(i=>{if(axis==='w')i.w=ref.w;else i.h=ref.h});render();status(axis==='w'?'Breiten angeglichen':'Höhen angeglichen')}
$('layerShowAll')?.addEventListener('click',()=>{currentItems().forEach(i=>i.hidden=false);render()});$('layerUnlockAll')?.addEventListener('click',()=>{currentItems().forEach(i=>i.locked=false);render()});
$('alignLeftBtn')?.addEventListener('click',()=>alignSelection('left'));$('alignCenterBtn')?.addEventListener('click',()=>alignSelection('center'));$('alignRightBtn')?.addEventListener('click',()=>alignSelection('right'));$('alignTopBtn')?.addEventListener('click',()=>alignSelection('top'));$('alignMiddleBtn')?.addEventListener('click',()=>alignSelection('middle'));$('alignBottomBtn')?.addEventListener('click',()=>alignSelection('bottom'));$('distributeHBtn')?.addEventListener('click',()=>distributeSelection('h'));$('distributeVBtn')?.addEventListener('click',()=>distributeSelection('v'));$('equalWidthBtn')?.addEventListener('click',()=>equalizeSelection('w'));$('equalHeightBtn')?.addEventListener('click',()=>equalizeSelection('h'));

