function ensureTableModel(item){if(!item||item.type!=='table')return item;item.tableRows=Math.max(1,Number(item.tableRows||4));item.tableCols=Math.max(1,Number(item.tableCols||3));if(!Array.isArray(item.tableData))item.tableData=defaultTableData(item.tableRows,item.tableCols);while(item.tableData.length<item.tableRows)item.tableData.push(Array.from({length:item.tableCols},()=>({text:'',bg:'',color:'',colSpan:1,rowSpan:1,hidden:false})));item.tableData=item.tableData.slice(0,item.tableRows);for(let r=0;r<item.tableRows;r++){while(item.tableData[r].length<item.tableCols)item.tableData[r].push({text:'',bg:'',color:'',colSpan:1,rowSpan:1,hidden:false});item.tableData[r]=item.tableData[r].slice(0,item.tableCols);item.tableData[r]=item.tableData[r].map(c=>typeof c==='string'?{text:c,bg:'',color:'',colSpan:1,rowSpan:1,hidden:false}:{text:c?.text||'',bg:c?.bg||'',color:c?.color||'',colSpan:Number(c?.colSpan||1),rowSpan:Number(c?.rowSpan||1),hidden:!!c?.hidden});}item.tableRowHeights=Array.isArray(item.tableRowHeights)?item.tableRowHeights.slice(0,item.tableRows):[];while(item.tableRowHeights.length<item.tableRows)item.tableRowHeights.push(42);item.tableColWidths=Array.isArray(item.tableColWidths)?item.tableColWidths.slice(0,item.tableCols):[];while(item.tableColWidths.length<item.tableCols)item.tableColWidths.push(120);item.tableBg=item.tableBg||'#ffffff';item.tableBorderColor=item.tableBorderColor||'#334155';item.tableBorderWidth=Number(item.tableBorderWidth??1);item.tableBorderStyle=item.tableBorderStyle||'solid';item.tableFontFamily=item.tableFontFamily||'Arial, sans-serif';item.tableFontSize=Number(item.tableFontSize||16);item.tableTextAlign=item.tableTextAlign||'left';item.tableVerticalAlign=item.tableVerticalAlign||'middle';item.tablePadding=Number(item.tablePadding??6);item.tableOpacity=Number(item.tableOpacity??100);item.tableHeader=item.tableHeader!==false;item.tableZebra=!!item.tableZebra;item.tableAutoFit=item.tableAutoFit!==false;item.tableHeaderBg=item.tableHeaderBg||'#e2e8f0';item.tableZebraBg=item.tableZebraBg||'#f8fafc';return item;}
const addItemBeforeTable=addItem;addItem=function(type,x=40,y=40){addItemBeforeTable(type,x,y);const i=currentItems().find(v=>v.id===selected);if(type==='table'&&i){i.text='';i.w=520;i.h=230;ensureTableModel(i);render();}};
function tableCell(item,r,c){ensureTableModel(item);return item.tableData[Math.max(0,Math.min(item.tableRows-1,r))][Math.max(0,Math.min(item.tableCols-1,c))];}
function tableTracks(item){if(item.tableAutoFit)return{cols:`repeat(${item.tableCols},minmax(0,1fr))`,rows:`repeat(${item.tableRows},minmax(0,1fr))`};return{cols:item.tableColWidths.map(v=>Math.max(30,v)+'px').join(' '),rows:item.tableRowHeights.map(v=>Math.max(18,v)+'px').join(' ')}}
function renderTableObject(el,item){ensureTableModel(item);const handles=[...el.querySelectorAll('.resize-handle')];el.innerHTML='';const grid=document.createElement('div');grid.className='fs-table-grid';const tracks=tableTracks(item);grid.style.gridTemplateColumns=tracks.cols;grid.style.gridTemplateRows=tracks.rows;grid.style.setProperty('--table-bg',item.tableBg);grid.style.setProperty('--table-border-color',item.tableBorderColor);grid.style.setProperty('--table-border-width',item.tableBorderWidth+'px');grid.style.setProperty('--table-border-style',item.tableBorderStyle);grid.style.setProperty('--table-font',item.tableFontFamily);grid.style.setProperty('--table-font-size',item.tableFontSize+'px');grid.style.setProperty('--table-padding',item.tablePadding+'px');grid.style.setProperty('--table-opacity',String(item.tableOpacity/100));grid.style.setProperty('--table-header-bg',item.tableHeaderBg);grid.style.setProperty('--table-zebra-bg',item.tableZebraBg);grid.style.textAlign=item.tableTextAlign;for(let r=0;r<item.tableRows;r++)for(let c=0;c<item.tableCols;c++){const cell=item.tableData[r][c];if(cell.hidden)continue;const d=document.createElement('div');d.className='fs-table-cell'+(r===item.tableRows-1?' last-row':'')+(c+cell.colSpan>=item.tableCols?' last-col':'')+(item.tableHeader&&r===0?' header':'')+(item.tableZebra&&r%2===1?' zebra':'')+(item.id===selected&&activeTableCell.row===r&&activeTableCell.col===c?' active-cell':'');d.dataset.row=r;d.dataset.col=c;d.textContent=resolveDynamicText(cell.text||'');d.style.alignItems=item.tableVerticalAlign==='top'?'flex-start':item.tableVerticalAlign==='bottom'?'flex-end':'center';d.style.justifyContent=item.tableTextAlign==='center'?'center':item.tableTextAlign==='right'?'flex-end':'flex-start';if(cell.bg)d.style.background=cell.bg;if(cell.color)d.style.color=cell.color;if(cell.colSpan>1)d.style.gridColumn=`span ${cell.colSpan}`;if(cell.rowSpan>1)d.style.gridRow=`span ${cell.rowSpan}`;d.addEventListener('pointerdown',ev=>{ev.stopPropagation();selected=item.id;selectedIds=new Set([item.id]);activeTableCell={row:r,col:c};render();});d.addEventListener('dblclick',ev=>{ev.stopPropagation();const val=prompt(`Zelle ${r+1}/${c+1} bearbeiten`,cell.text||'');if(val!==null){cell.text=val;render();}});grid.appendChild(d)}el.appendChild(grid);handles.forEach(h=>el.appendChild(h));}
const renderBeforeTables=render;render=function(){renderBeforeTables.apply(this,arguments);document.querySelectorAll('.designer-item[data-type="table"]').forEach(el=>{const i=currentItems().find(v=>v.id===el.dataset.id);if(i)renderTableObject(el,i)});};
function selectedTable(){const i=currentItems().find(v=>v.id===selected);return i?.type==='table'?ensureTableModel(i):null}
function updateTableControls(){const i=selectedTable();if(!i)return;activeTableCell.row=Math.min(activeTableCell.row,i.tableRows-1);activeTableCell.col=Math.min(activeTableCell.col,i.tableCols-1);const cell=tableCell(i,activeTableCell.row,activeTableCell.col);const set=(id,v)=>{if($(id))$(id).value=v};set('tableRows',i.tableRows);set('tableCols',i.tableCols);set('tableCellText',cell.text);set('tableRowHeight',i.tableRowHeights[activeTableCell.row]);set('tableColWidth',i.tableColWidths[activeTableCell.col]);set('tableCellBg',cell.bg||i.tableBg);set('tableCellColor',cell.color||i.color||'#1c2430');set('tableBg',i.tableBg);set('tableBorderColor',i.tableBorderColor);set('tableBorderWidth',i.tableBorderWidth);set('tableBorderStyle',i.tableBorderStyle);set('tableFontFamily',i.tableFontFamily);set('tableFontSize',i.tableFontSize);set('tableTextAlign',i.tableTextAlign);set('tableVerticalAlign',i.tableVerticalAlign);set('tablePadding',i.tablePadding);set('tableOpacity',i.tableOpacity);$('tablePaddingOut').value=i.tablePadding+' px';$('tableOpacityOut').value=i.tableOpacity+' %';$('tableHeader').checked=i.tableHeader;$('tableZebra').checked=i.tableZebra;$('tableAutoFit').checked=i.tableAutoFit;$('tableCellLabel').textContent=`Z ${activeTableCell.row+1} / S ${activeTableCell.col+1}`;}
const renderPropsBeforeTables=renderProps;renderProps=function(){renderPropsBeforeTables.apply(this,arguments);updateTableControls();};
function tableResize(rows,cols){const i=selectedTable();if(!i)return;i.tableRows=Math.max(1,Math.min(40,Number(rows)));i.tableCols=Math.max(1,Math.min(12,Number(cols)));ensureTableModel(i);activeTableCell={row:Math.min(activeTableCell.row,i.tableRows-1),col:Math.min(activeTableCell.col,i.tableCols-1)};render();}
function bindTableInput(id,fn,event='input'){const e=$(id);if(e)e.addEventListener(event,()=>{const i=selectedTable();if(!i)return;fn(i,e);render();});}
bindTableInput('tableRows',(i,e)=>tableResize(e.value,i.tableCols),'change');bindTableInput('tableCols',(i,e)=>tableResize(i.tableRows,e.value),'change');
bindTableInput('tableCellText',(i,e)=>tableCell(i,activeTableCell.row,activeTableCell.col).text=e.value);bindTableInput('tableRowHeight',(i,e)=>{i.tableRowHeights[activeTableCell.row]=Number(e.value);i.tableAutoFit=false;$('tableAutoFit').checked=false});bindTableInput('tableColWidth',(i,e)=>{i.tableColWidths[activeTableCell.col]=Number(e.value);i.tableAutoFit=false;$('tableAutoFit').checked=false});bindTableInput('tableCellBg',(i,e)=>tableCell(i,activeTableCell.row,activeTableCell.col).bg=e.value);bindTableInput('tableCellColor',(i,e)=>tableCell(i,activeTableCell.row,activeTableCell.col).color=e.value);bindTableInput('tableBg',(i,e)=>i.tableBg=e.value);bindTableInput('tableBorderColor',(i,e)=>i.tableBorderColor=e.value);bindTableInput('tableBorderWidth',(i,e)=>i.tableBorderWidth=Number(e.value));bindTableInput('tableBorderStyle',(i,e)=>i.tableBorderStyle=e.value,'change');bindTableInput('tableFontFamily',(i,e)=>i.tableFontFamily=e.value,'change');bindTableInput('tableFontSize',(i,e)=>i.tableFontSize=Number(e.value));bindTableInput('tableTextAlign',(i,e)=>i.tableTextAlign=e.value,'change');bindTableInput('tableVerticalAlign',(i,e)=>i.tableVerticalAlign=e.value,'change');bindTableInput('tablePadding',(i,e)=>{i.tablePadding=Number(e.value);$('tablePaddingOut').value=e.value+' px'});bindTableInput('tableOpacity',(i,e)=>{i.tableOpacity=Number(e.value);$('tableOpacityOut').value=e.value+' %'});bindTableInput('tableHeader',(i,e)=>i.tableHeader=e.checked,'change');bindTableInput('tableZebra',(i,e)=>i.tableZebra=e.checked,'change');bindTableInput('tableAutoFit',(i,e)=>i.tableAutoFit=e.checked,'change');
$('tableAddRow').onclick=()=>{const i=selectedTable();if(i)tableResize(i.tableRows+1,i.tableCols)};$('tableDeleteRow').onclick=()=>{const i=selectedTable();if(i&&i.tableRows>1){i.tableData.splice(activeTableCell.row,1);i.tableRowHeights.splice(activeTableCell.row,1);i.tableRows--;activeTableCell.row=Math.max(0,activeTableCell.row-1);render()}};$('tableAddCol').onclick=()=>{const i=selectedTable();if(i)tableResize(i.tableRows,i.tableCols+1)};$('tableDeleteCol').onclick=()=>{const i=selectedTable();if(i&&i.tableCols>1){i.tableData.forEach(r=>r.splice(activeTableCell.col,1));i.tableColWidths.splice(activeTableCell.col,1);i.tableCols--;activeTableCell.col=Math.max(0,activeTableCell.col-1);render()}};
$('tableMergeRight').onclick=()=>{const i=selectedTable();if(!i||activeTableCell.col>=i.tableCols-1)return status('Keine rechte Zelle zum Verbinden');const a=tableCell(i,activeTableCell.row,activeTableCell.col),b=tableCell(i,activeTableCell.row,activeTableCell.col+1);if(b.hidden)return;a.text=[a.text,b.text].filter(Boolean).join(' ');a.colSpan=Math.min(i.tableCols-activeTableCell.col,(a.colSpan||1)+1);b.hidden=true;render()};$('tableUnmerge').onclick=()=>{const i=selectedTable();if(!i)return;const a=tableCell(i,activeTableCell.row,activeTableCell.col),span=a.colSpan||1;for(let c=activeTableCell.col+1;c<Math.min(i.tableCols,activeTableCell.col+span);c++)tableCell(i,activeTableCell.row,c).hidden=false;a.colSpan=1;render()};
function applyTablePreset(kind){const i=selectedTable();if(!i)return;const presets={prices:[['Produkt','Beschreibung','Preis'],['Eierlikörpunsch','mit Sahne','4,50 €'],['Glühwein rot','0,2 l','3,50 €'],['Roter Feger','alkoholfrei','2,50 €']],program:[['Uhrzeit','Programmpunkt'],['17:00','Eröffnung'],['18:00','Bühnenprogramm'],['20:00','Musik und Ausklang']],hours:[['Tag','Öffnungszeiten'],['Montag–Freitag','15:00–21:00 Uhr'],['Samstag','11:00–22:00 Uhr'],['Sonntag','11:00–20:00 Uhr']]};const data=presets[kind];i.tableRows=data.length;i.tableCols=data[0].length;i.tableData=data.map(row=>row.map(text=>({text,bg:'',color:'',colSpan:1,rowSpan:1,hidden:false})));i.tableRowHeights=Array(i.tableRows).fill(42);i.tableColWidths=Array(i.tableCols).fill(kind==='prices'?165:220);i.tableHeader=true;i.tableZebra=true;i.tableAutoFit=true;i.name=kind==='prices'?'Preisliste':kind==='program'?'Programm':'Öffnungszeiten';activeTableCell={row:0,col:0};render();}
$('tablePresetPrices').onclick=()=>applyTablePreset('prices');$('tablePresetProgram').onclick=()=>applyTablePreset('program');$('tablePresetHours').onclick=()=>applyTablePreset('hours');
$('tableApplyPaste').onclick=()=>{const i=selectedTable(),raw=$('tablePasteData').value.trim();if(!i||!raw)return;const rows=raw.split(/\r?\n/).filter(Boolean).map(line=>line.split(/\t|;/));const cols=Math.max(...rows.map(r=>r.length));i.tableRows=Math.min(40,rows.length);i.tableCols=Math.min(12,cols);i.tableData=rows.slice(0,i.tableRows).map(r=>Array.from({length:i.tableCols},(_,c)=>({text:r[c]||'',bg:'',color:'',colSpan:1,rowSpan:1,hidden:false})));i.tableRowHeights=Array(i.tableRows).fill(42);i.tableColWidths=Array(i.tableCols).fill(140);activeTableCell={row:0,col:0};render();status('Tabellendaten übernommen')};
// Export/Preview: Tabellen als echtes HTML rendern
function tableToHtml(i){ensureTableModel(i);let out='<table style="border-collapse:collapse;width:100%;height:100%;font-family:'+escapeHtml(i.tableFontFamily)+';font-size:'+i.tableFontSize+'px;background:'+i.tableBg+';opacity:'+(i.tableOpacity/100)+'">';for(let r=0;r<i.tableRows;r++){out+='<tr>';for(let c=0;c<i.tableCols;c++){const cell=i.tableData[r][c];if(cell.hidden)continue;const tag=i.tableHeader&&r===0?'th':'td';out+=`<${tag} colspan="${cell.colSpan||1}" style="border:${i.tableBorderWidth}px ${i.tableBorderStyle} ${i.tableBorderColor};padding:${i.tablePadding}px;text-align:${i.tableTextAlign};vertical-align:${i.tableVerticalAlign};background:${cell.bg||(i.tableZebra&&r%2===1?i.tableZebraBg:i.tableHeader&&r===0?i.tableHeaderBg:'transparent')};color:${cell.color||i.color}">${escapeHtml(resolveDynamicText(cell.text||''))}</${tag}>`}out+='</tr>'}return out+'</table>'}
